def java_arr_to_python_16(v1):
    num_list = bytearray()
    for i in v1:
        if i < 0:
            i = i + 256
        num_list.append(i)
    # 转成16进制---比较
    res = [hex(item)[2:] for item in num_list]
    return ''.join(res)


